using GameEngine;

namespace DAL.EF;

/// <summary>
/// A row of the SavedGames table. The whole game is in <see cref="StateJson"/>; the other columns exist so the
/// saved games list can be read with one small query, without reading every game's JSON.
/// </summary>
public class SavedGame
{
    /// <summary>The engine's GameState.Id, never generated by the database, so ids match the JSON files.</summary>
    public Guid Id { get; set; }

    public string Name { get; set; } = "";
    public DateTime SavedAtUtc { get; set; }

    /// <summary>Copies of GameState.PlayerX/PlayerO, so the list can show who plays without reading the JSON.</summary>
    public EPlayerType PlayerX { get; set; }

    public EPlayerType PlayerO { get; set; }

    /// <summary>Written and read by GameEngine.GameStateJson: exactly the text a .game.json file contains.</summary>
    public string StateJson { get; set; } = "";

    /// <summary>Foreign key: every saved game belongs to one stored configuration.</summary>
    public int ConfigurationId { get; set; }

    /// <summary>Navigation property: filled only when the query asks for it (a join).</summary>
    public Configuration? Configuration { get; set; }
}
